3	const fs = require('fs');
4	
5	const STATE_FILE = '/Users/marcelspatz/NUDIMMUD/.claude/state/token-session.json';
6	
7	// Tools with high token cost — flag for potential offload
8	const HEAVY_TOOLS = new Set(['Agent', 'WebSearch', 'WebFetch', 'TaskCreate']);
9	const LIGHT_TOOLS = new Set(['Read', 'Bash', 'Edit', 'Write', 'ToolSearch']);
10	
11	try {
12	    const input = fs.readFileSync(0, 'utf-8').trim();
13	    if (!input) process.exit(0);
14	    const event = JSON.parse(input);
15	
16	    const toolName = event?.tool_name || event?.tool || '';
17	    const toolInput = JSON.stringify(event?.tool_input || {});
18	
19	    // Estimate cost: heavy tools + large inputs = flag
20	    const isHeavy = HEAVY_TOOLS.has(toolName);
21	    const inputSize = toolInput.length;
22	    const score = (isHeavy ? 600 : 100) + Math.floor(inputSize / 10);
23	
24	    // Read current session token state
25	    let sessionTokens = 0;
26	    let contextPct = 0;
27	    try {
28	        const s = JSON.parse(fs.readFileSync(STATE_FILE, 'utf-8'));
29	        sessionTokens = s.totalTokens || 0;
30	        contextPct = s.context || 0;
31	    } catch (_) {}
32	
33	    // High context pressure — warn
34	    if (contextPct > 75 && isHeavy) {
35	        console.error(JSON.stringify({
36	            hookSpecificOutput: {
37	                hookEventName: 'PreToolUse',
38	                additionalContext: `TOKEN_ECONOMY: Context at ${contextPct}% — tool "${toolName}" is expensive (score: ${score}). Consider offloading to @deepseek or @qwen. Session total: ${sessionTokens.toLocaleString()} tokens.`
39	            }
40	        }));
41	    }
42	
43	    // Very high — block with recommendation (score > 2000)
44	    if (score > 2000 && contextPct > 60) {
45	        console.error(JSON.stringify({
46	            hookSpecificOutput: {
47	                hookEventName: 'PreToolUse',
48	                additionalContext: `TOKEN_ECONOMY: High-cost operation detected for "${toolName}" (score: ${score}). Recommend: offload via @swarm or @kimi. Proceed only if reasoning value justifies spend.`
49	            }
50	        }));
51	    }
52	
53	    process.exit(0);
54	} catch (e) {
55	    process.exit(0);
56	}
