    "defaultMode": "default",           // "default", "acceptEdits", "plan", "auto", "bypassPermissions"
    "allow": [
      "Bash(npm run *)",
      "Read(./src/**)",
      "Edit(./src/**)",
      "WebFetch(domain:github.com)"
    ],
    "deny": [
      "Bash(rm -rf *)",
      "Read(./.env)"
    ]
  },

  // ===== STATUS LINE =====
  "statusLine": {
    "type": "command",
    "command": "node $CLAUDE_PROJECT_DIR/.claude/hooks/token-status.js"
  },

  // ===== HOOKS (TERMINAL FEEDBACK) =====
  "hooks": {
    "PreToolUse": [
      {
        "matcher": "",
        "hooks": [
          {
            "type": "command",
            "command": "node $CLAUDE_PROJECT_DIR/.claude/hooks/pre-tool-use.js"
          }
        ]
      }
    ],
    "PostToolUse": [
      {
        "matcher": "",
        "hooks": [
          {
            "type": "command",
            "command": "node $CLAUDE_PROJECT_DIR/.claude/hooks/post-tool-use.js",
            "async": true
          }
        ]
      }
    ],
    "Stop": [
      {
        "matcher": "",
        "hooks": [
          {
            "type": "command",
            "command": "node $CLAUDE_PROJECT_DIR/.claude/hooks/on-stop.js",
            "async": true
          }
        ]
      }
    ]
  },

  // ===== ENVIRONMENT =====
  "env": {
    "CLAUDE_CODE_ENABLE_TELEMETRY": "0",
    "CLAUDE_VERBOSITY": "2"
  },

  "language": "en",
  "autoUpdatesChannel": "stable"
