#!/usr/bin/env node
const fs = require('fs');

const STATE_FILE = '.claude/state/token-session.json';
const input = fs.readFileSync(0, 'utf-8').trim();
if (!input) process.exit(0);

const event = JSON.parse(input);
const toolName = event?.tool_name || '';

let contextPct = 0;
try {
  const state = JSON.parse(fs.readFileSync(STATE_FILE, 'utf-8'));
  contextPct = state.context || 0;
} catch (_) {}

if (contextPct > 85) {
  console.error(`\n⚠️  CONTEXT HIGH: ${contextPct}% full. "${toolName}" may fail or overflow.`);
  console.error(`Consider /compact or /clear before proceeding.\n`);
}

process.exit(0);
```

