### Full Extended Token-Status Hook

```javascript
#!/usr/bin/env node
const fs = require('fs');
const { execSync } = require('child_process');

const STATE_DIR = '/Users/marcelspatz/NUDIMMUD/.claude/state';
const SESSION_FILE = `${STATE_DIR}/token-session.json`;

try {
  const input = fs.readFileSync(0, 'utf-8').trim();
  if (!input) {
    console.log('🔌 Offline');
    process.exit(0);
  }

  const data = JSON.parse(input);
  const model = data?.model?.display_name || data?.model?.name || 'Claude';
  const context = data?.context_window?.used_percentage || 0;
  const inputTokens = data?.usage?.input_tokens || 0;
  const outputTokens = data?.usage?.output_tokens || 0;
  const totalTokens = data?.usage?.total_tokens || (inputTokens + outputTokens) || 0;
  const cost = data?.cost || 0;

  // Persist session state
  try {
    const existing = fs.existsSync(SESSION_FILE) 
      ? JSON.parse(fs.readFileSync(SESSION_FILE, 'utf-8')) 
      : { inputTokens: 0, outputTokens: 0, totalTokens: 0, cost: 0 };

    fs.mkdirSync(STATE_DIR, { recursive: true });
    fs.writeFileSync(SESSION_FILE, JSON.stringify({
      model,
      context,
      inputTokens: (existing.inputTokens || 0) + inputTokens,
      outputTokens: (existing.outputTokens || 0) + outputTokens,
      totalTokens: (existing.totalTokens || 0) + totalTokens,
      cost: parseFloat(((existing.cost || 0) + cost).toFixed(6)),
      updatedAt: new Date().toISOString()
    }, null, 2));
  } catch (_) {}

  const parts = [];

  // Model
  parts.push(`🧠 ${model}`);

  // Context fill
  const contextIcon = context < 50 ? '🟢' : (context < 85 ? '🟡' : '🔴');
  parts.push(`${contextIcon} ${context}%`);

  // Token accounting
  if (totalTokens > 0) {
    parts.push(`🔄 ${totalTokens.toLocaleString()}`);
    parts.push(`↑${inputTokens} ↓${outputTokens}`);
  }

  // Cost
  if (cost > 0) {
    parts.push(`💰 $${cost.toFixed(4)}`);
  }

  // Git branch
  try {
    const branch = execSync('git branch --show-current', { encoding: 'utf-8' }).trim();
    parts.push(`🌿 ${branch}`);
  } catch (_) {}

  console.log(parts.join(' │ '));
} catch (e) {
  console.log(`⚠️ Status Error: ${e.message}`);
}
```

